Word load(const void* p,Word offset=0) { Word result; std::memcpy(&result,static_cast<const unsigned char*>(p)+offset,4); return result; }
void store(void* p,Word offset,Word value) { std::memcpy(static_cast<unsigned char*>(p)+offset,&value,4); }
std::uint8_t __fastcall enter_original(void* renderer) { return bsp::enter_native_renderer_optional_guard_00b33ad0(renderer,globals); }
void __fastcall leave_original(void* renderer,Word,Word ignored) { bsp::leave_native_renderer_optional_guard_00b33b00(renderer,ignored,globals); }
[[noreturn]] EXCEPTION_DISPOSITION __cdecl unexpected_original_seh(EXCEPTION_RECORD*,void*,CONTEXT*,void*) {
    TerminateProcess(GetCurrentProcess(),42); __assume(0);
}
class Original {
    void* code_; std::size_t size_;
public:
    template<std::size_t N> explicit Original(const unsigned char (&data)[N]):
        code_(VirtualAlloc(nullptr,N,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE)),size_(N) {
        require(code_!=nullptr,"VirtualAlloc"); std::memcpy(code_,data,N);
    }
    ~Original() { VirtualFree(code_,0,MEM_RELEASE); }
    void* pointer() const { return code_; }
    template<class F> void branch(std::size_t offset,F function,unsigned char opcode=0xe8) {
        auto* p=static_cast<unsigned char*>(code_); require(p[offset]==opcode,"branch relocation");
        const Word displacement=static_cast<Word>(reinterpret_cast<std::uintptr_t>(function)-reinterpret_cast<std::uintptr_t>(p+offset+5));
        std::memcpy(p+offset+1,&displacement,4);
    }
    void absolute(Word offset,Word expected,Word replacement) {
        require(load(code_,offset)==expected,"absolute relocation"); store(code_,offset,replacement);
    }
    void finish() {
        DWORD old; require(VirtualProtect(code_,size_,PAGE_EXECUTE_READ,&old)!=0,"VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(),code_,size_)!=0,"FlushInstructionCache");
    }
};
Word freed_address=0,free_calls=0;
void __cdecl free_original(void* owner) noexcept {
    if(load(owner)!=0x00ceb130 || load(owner,0x10)!=0 || globals.nesting_04!=0) TerminateProcess(GetCurrentProcess(),43);
    freed_address=address(owner); ++free_calls; bsp::singleton_lifetime_free(owner);
}
std::array<Word,11> renderer_tokens() {
    std::array<Word,11> result{}; std::memcpy(result.data(),original_00d5f0a8,44); return result;
}
const std::array<Word,11> actual_renderer_profile=renderer_tokens();
const std::array<Word,2> actual_query_profile{0x00bd30e0,0x00b5fe40};
struct Renderer {
    alignas(4) std::array<unsigned char,0x19b0> bytes;
    bsp::TrackedCriticalSection lock{};
    std::array<Word,4> rows{};
    std::array<Word,11> callable_table{};
    Renderer(bool native,void* unregister_code) {
        bytes.fill(0xa5); InitializeCriticalSection(&lock.native); lock.depth=0;
        callable_table[10]=address(unregister_code);
        store(raw(),0,native?address(callable_table.data()):0x00d5f0a8); store(raw(),4,address(&lock));
        store(raw(),0x19a0,address(rows.data())); store(raw(),0x19a4,0); store(raw(),0x19a8,4);
    }
    ~Renderer() { while(lock.native.RecursionCount>0) LeaveCriticalSection(&lock.native); DeleteCriticalSection(&lock.native); }
    void* raw() { return bytes.data(); }
    Word count() { return load(raw(),0x19a4); }
    void guards() {
        for(Word i=0;i<bytes.size();++i) if(i>=8 && !(i>=0x19a0&&i<0x19ac)) require(bytes[i]==0xa5,"renderer extents");
        require(load(raw(),0x19a0)==address(rows.data()) && load(raw(),0x19a8)==4,"registry storage/capacity retained");
        require(lock.depth==0 && lock.native.RecursionCount==0,"actual optional guard balanced");
    }
};
struct Fixture;
struct Com { Word* table; Fixture* fixture; bool spare; };
struct Snapshot {
    Word first_count,second_count,published,release_calls,spare_calls,mode,observed,nesting;
    std::array<Word,4> first_rows,second_rows;
    bool operator==(const Snapshot&) const=default;
};
struct Fixture {
    Renderer first,second;
    Word* query;
    bool query_live=true,throw_release=false,disable_on_release=false;
    unsigned releases=0,spare_releases=0;
    std::array<Word,3> com_table{};
    Com com{com_table.data(),this,false},spare{com_table.data(),this,true};
    bsp::NativeRendererQueryTerminalContext context{published_renderer,globals,actual_query_profile.data(),actual_renderer_profile.data()};
    Fixture(bool native,void* unregister_code,bool has_com):first(native,unregister_code),second(native,unregister_code),
        query(static_cast<Word*>(bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object,32,32}))) {
        for(Word i=0;i<8;++i) query[i]=0x55550000u+i;
        query[0]=0x00d62ad0; query[4]=has_com?address(&com):0;
        first.rows={address(query),0x11111111,0x22222222,0x33333333}; store(first.raw(),0x19a4,1);
        second.rows={0x11111111,address(query),address(query),0x22222222}; store(second.raw(),0x19a4,4);
        published_renderer=first.raw(); globals.mode_00=1; globals.observed_mode_01=0; globals.nesting_04=0;
        globals.preserved_02[0]=0x65; globals.preserved_02[1]=0x76; freed_address=0; free_calls=0;
    }
    ~Fixture() { if(query_live) bsp::singleton_lifetime_free(query); }
    void verify_query(bool released) {
        require(query[0]==0x00ceb130 && query[4]==0,"query base/COM postimage");
        require(query[1]==0x55550001 && query[2]==(released?0xcafebabeu:0x55550002u) && query[3]==0x55550003,"untouched references/state/samples except provider write");
        for(Word i=5;i<8;++i) require(query[i]==0x55550000u+i,"query trailing guards");
    }
    Snapshot snapshot() {
        first.guards(); second.guards(); require(globals.preserved_02[0]==0x65 && globals.preserved_02[1]==0x76,"sync padding");
        auto normalize=[&](std::array<Word,4> rows) { for(auto& value:rows) if(value==address(query)) value=0xf00dface; return rows; };
        return {first.count(),second.count(),published_renderer==second.raw()?2u:1u,releases,spare_releases,globals.mode_00,globals.observed_mode_01,globals.nesting_04,normalize(first.rows),normalize(second.rows)};
    }
};
Word __stdcall release_com(Com* current) {
    auto& f=*current->fixture;
    if(current->spare) { ++f.spare_releases; return 0; }
    ++f.releases;
    require(f.query[0]==0x00d62ad0 && f.query[4]==address(&f.com),"stamp and captured COM before release");
    require(published_renderer==f.first.raw() && globals.nesting_04==0,"renderer reload/guard occur after release");
    f.query[2]=0xcafebabe; f.query[4]=address(&f.spare); published_renderer=f.second.raw();
    if(f.disable_on_release) globals.mode_00=0;
    if(f.throw_release) throw std::runtime_error("scripted Release exception");
    return 0x42;
}
Snapshot normal_case(void* destructor_code,void* scalar_code,void* invoker_code,void* unregister_code,bool native,unsigned kind) {
    Fixture f(native,unregister_code,kind!=1); f.com_table[2]=reinterpret_cast<Word>(&release_com);
    f.disable_on_release=kind==2;
    if(kind==0) {
        if(native) reinterpret_cast<Entry>(destructor_code)(f.query); else bsp::destroy_native_renderer_query_00b5fda0(f.query,f.context);
        f.verify_query(true);
    } else if(kind==1) {
        void* result=native?reinterpret_cast<Scalar>(scalar_code)(f.query,0,2):bsp::delete_native_renderer_query_00b5fe40(f.query,2,f.context);
        require(address(result)==address(f.query) && free_calls==0,"scalar bit1 does not free and returns owner"); f.verify_query(false);
    } else {
        const std::array<Word,2> callable_query{address(invoker_code),address(scalar_code)};
        if(native) { f.query[0]=address(callable_query.data()); reinterpret_cast<Entry>(invoker_code)(f.query); }
        else bsp::invoke_native_renderer_query_delete_00bd30e0(f.query,f.context);
        f.query_live=false;
        if(native) require(free_calls==1 && freed_address==address(f.query),"flags1 scalar frees only after full cleanup");
    }
    if(kind==1) require(f.first.count()==0 && f.second.count()==4 && f.releases==0,"null COM skips release/unregisters current initial renderer");
    else require(f.first.count()==1 && f.second.count()==3 && f.second.rows[1]==0x22222222 && f.second.rows[2]==address(f.query) && f.second.rows[3]==0x22222222 && f.releases==1 && f.spare_releases==0,"current publication, first-match swap and captured Release/clear");
    require(globals.observed_mode_01==(kind==2?0u:1u),"current mode chooses actual optional guard");
    return f.snapshot();
}
void source_exception(void* unregister_code) {
    Fixture f(false,unregister_code,true); f.com_table[2]=reinterpret_cast<Word>(&release_com); f.throw_release=true;
    bool caught=false; try { (void)bsp::delete_native_renderer_query_00b5fe40(f.query,1,f.context); } catch(const std::runtime_error&) { caught=true; }
    require(caught && f.query[0]==0x00ceb130 && f.query[4]==address(&f.spare) && f.query[2]==0xcafebabe,"exception restores base and retains provider writes without clear");
    require(f.first.count()==1 && f.second.count()==4 && published_renderer==f.second.raw() && f.releases==1 && f.spare_releases==0 && globals.nesting_04==0,"exception skips unregister/free/retry and retains publication");
    f.first.guards(); f.second.guards();
