void helper_edges(void* remove_code,void* base_code,void* invoker_code) {
    std::array<Word,4> a{},b{}; a[0]=address(a.data()+1); b[0]=address(b.data()+1); a[1]=b[1]=2; a[2]=b[2]=9; a[3]=b[3]=0x87654321; const Word sought=2;
