    reinterpret_cast<Entry>(base_code)(native_base.data()); bsp::destroy_native_renderer_query_base_00b5fd40(source_base.data());
    require(native_base==source_base && native_base[0]==0x00ceb130,"base wrapper exact postimage");
    void* volatile no_renderer=nullptr;
    bsp::NativeRendererQueryTerminalContext unused{no_renderer,globals,nullptr,nullptr};
    reinterpret_cast<Entry>(invoker_code)(nullptr); bsp::invoke_native_renderer_query_delete_00bd30e0(nullptr,unused);
