void module_record(const wchar_t* name,HMODULE module,const char* category) {
    if(!module) { std::printf("UNLOADED_RUNTIME|%ls\n",name); return; }
    wchar_t reported[1024],canonical[1024]; const DWORD n=GetModuleFileNameW(module,reported,1024); require(n&&n<1024,"module path");
    HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr); require(file!=INVALID_HANDLE_VALUE,"module file");
    const DWORD m=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED); CloseHandle(file); require(m&&m<1024,"canonical module file");
    const auto* data=reinterpret_cast<const unsigned char*>(module); const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(data); const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(data+dos->e_lfanew);
