        helper_edges(remove.pointer(),base.pointer(),invoke.pointer()); source_exception(unregister_query.pointer());
        for(const auto* name:{L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll",L"kernel32.dll",L"ntdll.dll"}) module_record(name,GetModuleHandleW(name),"LOADED_RUNTIME");
        provider_record(L"EnterCriticalSection",reinterpret_cast<void*>(&::EnterCriticalSection)); provider_record(L"LeaveCriticalSection",reinterpret_cast<void*>(&::LeaveCriticalSection));
